{"witnessCode": "import { describe, it } from 'node:test';
import assert from 'node:assert/strict';
import normalizeUrl from '../index.js';

describe('WWW strip regression', () => {
  it('should not strip www for 1-char TLD in base', () => {
    const input = 'www.example.a';
    const opts = { stripWWW: true };
    const result = normalizeUrl(input, opts);
    assert.ok(result.includes('www.'), `Expected result to contain 'www.', got ${result}`);
  });
});"}
